#[test]
fn authentic_page_admission_precedes_any_partition_graph_edit() {
    use super::super::apply_vt_conformance_mutation;
    for dangling in [false, true] {
        let mut base = PdfSnapshot::default();
        let catalog = support::insert_object(&mut base, support::dict(vec![("Type", PdfObject::Name("Catalog".into()))]));
        base.trailer.push(crate::standards::v1_7::subsets::base::schema::snapshot::PdfDictEntry::new("Root", PdfObject::Ref(catalog)));
        if dangling { support::set_entry(&mut base, catalog, "Pages", PdfObject::Ref(crate::standards::v1_7::subsets::base::schema::snapshot::ObjRef { num: 999, gen: 0 })); }
        let before = base.clone();
        let mutation = PdfVtMutation::SetDpartRoot(SetDpartRoot { job: "neutral job".into() });
        let outcome = apply_vt_conformance_mutation(&mut base, &mutation);
        assert!(!outcome.messages().is_empty(), "missing genuine reachable Page must refuse");
        assert_eq!(base, before, "refusal must precede allocation or Catalog mutation");
        assert!(<SetDpartRoot as MutationKind<PdfSnapshot, PdfVtMutation>>::inverse(&SetDpartRoot { job: "neutral job".into() }, &before).is_err());
    }
}

#[test]
fn genuine_partition_graph_keeps_parent_start_and_exact_inverse() {
    use super::super::apply_vt_conformance_mutation;
    use crate::standards::v1_7::subsets::base::schema::snapshot::PdfPage;
    let mut base = PdfSnapshot::default();
    let catalog = support::insert_object(&mut base, support::dict(vec![("Type", PdfObject::Name("Catalog".into()))]));
        base.trailer.push(crate::standards::v1_7::subsets::base::schema::snapshot::PdfDictEntry::new("Root", PdfObject::Ref(catalog)));
    let pages = support::insert_object(&mut base, support::dict(vec![("Type", PdfObject::Name("Pages".into())), ("Count", PdfObject::Int(1))]));
    let page = support::insert_object(&mut base, support::dict(vec![("Type", PdfObject::Name("Page".into())), ("Parent", PdfObject::Ref(pages)), ("MediaBox", PdfObject::numbers(&[0.0, 0.0, 100.0, 100.0]))]));
    support::set_entry(&mut base, catalog, "Pages", PdfObject::Ref(pages));
    support::set_entry(&mut base, pages, "Kids", PdfObject::Array(vec![PdfObject::Ref(page)]));
    base.pages.push(PdfPage::new(100.0, 100.0));
    let mutation = SetDpartRoot { job: "neutral job".into() };
    let inverse = <SetDpartRoot as MutationKind<PdfSnapshot, PdfVtMutation>>::inverse(&mutation, &base).unwrap();
    let mut next = base.clone();
    let outcome = apply_vt_conformance_mutation(&mut next, &PdfVtMutation::SetDpartRoot(mutation));
    assert!(outcome.messages().is_empty());
    let root = support::catalog_entry(&next, "DPartRoot").and_then(PdfObject::as_ref).unwrap();
    let node = support::dpart_root_node(&next).unwrap();
    let value = support::object(&next, node).unwrap();
    assert_eq!(value.dict_get("Parent").and_then(PdfObject::as_ref), Some(root));
    assert_eq!(value.dict_get("Start").and_then(PdfObject::as_ref), Some(page));
    assert_eq!(support::dpart_job(&next).as_deref(), Some("neutral job"));
    for undo in inverse { assert!(apply_vt_conformance_mutation(&mut next, &undo).messages().is_empty()); }
    assert_eq!(next, base, "inverse must restore the entire owner, including object vector");
}
